(async () => {
  const [cmd, arg] = process.argv.slice(2);
  try {
    if (cmd === "run" && arg) process.exitCode = stageRun(arg);
    else if (cmd === "locked" && arg) process.exitCode = await stageLocked(arg);
    // Exit explicitly: a pending race timer (stop timeout) must not keep the inner stage alive.
    else if (cmd === "inner" && arg) process.exit(await stageInner(arg));
    else if (cmd === "setup" && arg) { const j = await ensureJdk(Number(arg)); process.stdout.write(JSON.stringify({ home: j.home, release: j.release, sha256: j.sha256, fetched: j.fetched, version: jdkVersion(j.home) }) + "\n"); }
    else { process.stderr.write("usage: runner.js run <spec.json> | setup <21|25>\n"); process.exitCode = 2; }
  } catch (e) {
    log(`fatal: ${e.stack || e.message}`);
    process.exitCode = 1;
  }
})();

