// Test Flight spec validation + resolution against the version registry. Pure (no I/O): fails closed on anything
// the registry cannot vouch for (unknown version, no pinned Paper server jar).
import { getVersion, type VersionRow } from "../versions/registry";
import type { CheckId, ResolvedSpec, TestFlightSpec, LogMatcher } from "./types";
import { CHECK_IDS } from "./types";

export const TF_DEFAULT_ROOT = "/tank/nxeon-build/tmp/testflight";
export const DEFAULT_TIMEOUTS = { bootSec: 180, rconSec: 10, stopSec: 45, totalSec: 420 } as const;
export const DEFAULT_MEMORY = { xmxMb: 1024, rssCapMb: 1800 } as const;
const RESERVED_COMMANDS = /^\/?(stop|restart|op|deop|reload)\b/i;
const SHA256 = /^[0-9a-f]{64}$/;

function checkMatchers(list: LogMatcher[] | undefined, key: string, errs: string[]) {
  for (const [i, m] of (list ?? []).entries()) {
    if (!m || typeof m.pattern !== "string" || !m.pattern) { errs.push(`${key}[${i}]: pattern is required`); continue; }
    if (m.pattern.length > 400) errs.push(`${key}[${i}]: pattern longer than 400 chars`);
    try { new RegExp(m.pattern, (m.flags ?? "").replace(/[^imsu]/g, "")); } catch (e) { errs.push(`${key}[${i}]: ${(e as Error).message}`); }
  }
}

export type PinnedRow = VersionRow & { paperBuild: number; paperServerSha256: string };
export type SpecCheck = { ok: true; row: PinnedRow } | { ok: false; errors: string[] };

/** Validate a caller spec. `lookup` is injectable for tests; defaults to the real registry. */
export function validateSpec(spec: TestFlightSpec, lookup: (id: string) => VersionRow | null = getVersion): SpecCheck {
  const errs: string[] = [];
  const row = lookup(String(spec?.version ?? ""));
  if (!row) errs.push(`Minecraft ${spec?.version} is not in the version registry`);
  else {
    if (!row.paperBuild || !Number.isInteger(row.paperBuild)) errs.push(`${row.id} has no pinned Paper server build, so it cannot be test-flown`);
    if (!SHA256.test(String(row.paperServerSha256 ?? ""))) errs.push(`${row.id} has no pinned Paper server sha256`);
  }
  const arts = [...(spec.plugins ?? []).map((a, i) => ["plugins", i, a] as const), ...(spec.datapacks ?? []).map((a, i) => ["datapacks", i, a] as const)];
  for (const [k, i, a] of arts) {
    const hasLocal = typeof a?.localPath === "string" && a.localPath.length > 0;
    const hasRemote = typeof a?.remotePath === "string" && a.remotePath.length > 0;
    if (hasLocal === hasRemote) errs.push(`${k}[${i}]: give exactly one of localPath or remotePath`);
    if (a?.sha256 != null && !SHA256.test(a.sha256)) errs.push(`${k}[${i}]: sha256 must be 64 lowercase hex chars`);
    if (k === "plugins" && !/\.jar$/.test(String(a?.localPath ?? a?.remotePath ?? ""))) errs.push(`plugins[${i}]: must be a .jar`);
  }
  for (const [i, d] of (spec.datapacks ?? []).entries()) if (!/^[a-z0-9_.-]{1,64}$/.test(String(d?.name ?? ""))) errs.push(`datapacks[${i}].name must be 1-64 chars of a-z 0-9 _ . -`);
  const pluginNames = new Set<string>();
  for (const p of spec.plugins ?? []) {
    const b = String(p.localPath ?? p.remotePath ?? "").split("/").pop()!;
    if (pluginNames.has(b)) errs.push(`two plugins share the file name ${b}`);
    pluginNames.add(b);
  }
  for (const [i, c] of (spec.rcon ?? []).entries()) {
    const cmd = String(c?.command ?? "");
    if (!cmd.trim() || cmd.length > 200 || /[\r\n]/.test(cmd)) errs.push(`rcon[${i}].command must be one line of 1-200 chars`);
    if (RESERVED_COMMANDS.test(cmd.trim())) errs.push(`rcon[${i}]: '${cmd}' is reserved for the runner`);
    if (c.expect != null && !Array.isArray(c.expect)) errs.push(`rcon[${i}].expect must be an array of strings`);
  }
  checkMatchers(spec.logMatchers, "logMatchers", errs);
  checkMatchers(spec.logIgnore, "logIgnore", errs);
  if (spec.logMatchers && spec.logMatchers.length === 0) errs.push("logMatchers: an empty list would make the log check vacuous; omit it to use the defaults");
  const t = spec.timeouts ?? {};
  for (const [k, max] of [["bootSec", 600], ["rconSec", 60], ["stopSec", 120], ["totalSec", 900]] as const) {
    const v = t[k];
    if (v != null && !(Number.isFinite(v) && v > 0 && v <= max)) errs.push(`timeouts.${k} must be 1-${max}`);
  }
  const m = spec.memory ?? {};
  if (m.xmxMb != null && !(Number.isInteger(m.xmxMb) && m.xmxMb >= 256 && m.xmxMb <= 1024)) errs.push("memory.xmxMb must be 256-1024 (node-2 allows at most -Xmx1g)");
  if (m.rssCapMb != null && !(Number.isInteger(m.rssCapMb) && m.rssCapMb >= 512 && m.rssCapMb <= 2048)) errs.push("memory.rssCapMb must be 512-2048");
  for (const s of spec.requireStages ?? []) if (!(CHECK_IDS as readonly string[]).includes(s)) errs.push(`requireStages: unknown stage ${s}`);
  if (errs.length || !row) return { ok: false, errors: errs };
  return { ok: true, row: row as PinnedRow };
}

/** Required stages for a spec. The summary uses THIS (what we asked for), not the runner's own flags. */
export function requiredStages(spec: TestFlightSpec): Set<CheckId> {
  const req = new Set<CheckId>(["boot_done", "startup_log_clean", "clean_stop", "no_leaks"]);
  if ((spec.plugins ?? []).length) req.add("plugins_enabled");
  if ((spec.rcon ?? []).length || (spec.datapacks ?? []).length) req.add("rcon_checks");
  for (const s of spec.requireStages ?? []) req.add(s);
  return req;
}

const base = (p: string) => p.split("/").pop()!;

/** Resolve a validated spec for the runner. Local artifacts are mapped to `<root>/inbox/<runId>/<file>`. */
export function resolveSpec(spec: TestFlightSpec, opts: { runId: string; root?: string; lookup?: (id: string) => VersionRow | null }): ResolvedSpec {
  const v = validateSpec(spec, opts.lookup);
  if (!v.ok) throw new Error(`invalid Test Flight spec: ${v.errors.join("; ")}`);
  if (!/^[a-z0-9][a-z0-9-]{5,63}$/.test(opts.runId)) throw new Error("runId must be 6-64 chars of a-z, 0-9, -");
  const root = (opts.root ?? TF_DEFAULT_ROOT).replace(/\/$/, "");
  const inbox = `${root}/inbox/${opts.runId}`;
  return {
    schema: 1,
    runId: opts.runId,
    version: v.row.id,
    javaRelease: v.row.javaRelease,
    paper: { build: v.row.paperBuild, sha256: v.row.paperServerSha256 },
    plugins: (spec.plugins ?? []).map((p) => ({ path: p.remotePath ?? `${inbox}/${base(p.localPath!)}`, ...(p.sha256 ? { sha256: p.sha256 } : {}) })),
    datapacks: (spec.datapacks ?? []).map((d) => ({ name: d.name, path: d.remotePath ?? `${inbox}/dp-${d.name}` })),
    ...(spec.resourcePack ? { resourcePack: spec.resourcePack } : {}),
    rcon: spec.rcon ?? [],
    ...(spec.logMatchers ? { logMatchers: spec.logMatchers } : {}),
    ...(spec.logIgnore ? { logIgnore: spec.logIgnore } : {}),
    timeouts: { ...DEFAULT_TIMEOUTS, ...(spec.timeouts ?? {}) },
    memory: { ...DEFAULT_MEMORY, ...(spec.memory ?? {}) },
    keepDir: !!spec.keepDir,
  };
}

// Version-support registry: the one place that says what each Minecraft version needs (JDK, pack formats,
// capabilities) and whether Cyrus may build for it. Replaces scattered version lists and the old packFormatFor.
// Data lives in registry.json so the Next.js app and the plain-Node build service can read the same file.
import registryData from "./registry.json";

export type Capability = "itemModelDefinitions" | "dialogApi" | "adventure5" | "dataComponentsStable";
export type FormatVersion = { major: number; minor: number };
export type VersionRow = {
  id: string;
  family: "1.21" | "26";
  javaRelease: 21 | 25;
  status: "supported" | "preview" | "legacy" | "blocked";
  buildable: boolean;
  paperCoordinate: string | null;
  /** Exact stable Paper SERVER build and its jar sha256 (what Test Flight boots); independent of paperCoordinate
   *  (the compile API). null/absent = no pin, so the version cannot be test-flown. */
  paperBuild?: number | null;
  paperServerSha256?: string | null;
  resourcePack: FormatVersion | null;
  dataPack: FormatVersion | null;
  resourcePackClientVerified: boolean;
  capabilities: Capability[];
};

export const VERSIONS: readonly VersionRow[] = registryData.versions as VersionRow[];

/** Exact match only: a version the registry does not list is unknown, never guessed. */
export function getVersion(id: string): VersionRow | null {
  return VERSIONS.find((v) => v.id === id) ?? null;
}

export const buildableVersions = (): VersionRow[] => VERSIONS.filter((v) => v.buildable);
export const hasCapability = (id: string, c: Capability): boolean => !!getVersion(id)?.capabilities.includes(c);

export type PackFormatResult =
  | { ok: true; format: FormatVersion; clientVerified: boolean }
  | { ok: false; error: string };

/** Resource-pack format for a version. Fails closed: unknown version, unknown number, or no item-model support. */
export function resourcePackFormat(mc: string, opts: { needsItemModels?: boolean } = {}): PackFormatResult {
  const v = getVersion(mc);
  if (!v) return { ok: false, error: `Minecraft ${mc} is not in the version registry` };
  if (!v.resourcePack) return { ok: false, error: `resource pack format for ${mc} is not verified yet` };
  if (opts.needsItemModels && !v.capabilities.includes("itemModelDefinitions")) {
    return { ok: false, error: `${mc} has no item model definitions (needs 1.21.4+); a legacy custom-model-data emitter is not built yet` };
  }
  return { ok: true, format: v.resourcePack, clientVerified: v.resourcePackClientVerified };
}
// A Minecraft resource pack from validated texture specs: one item model per texture, wired the 1.21.4+ way
// (assets/<ns>/items/<name>.json is what `ItemMeta.setItemModel(new NamespacedKey("<ns>", "<name>"))` points at).
import { createHash } from "node:crypto";
import { checkSpec, type TextureSpec } from "./dsl";
import { encodePng } from "./png";
import { render } from "./render";
import { zip } from "./zip";
import { getVersion, resourcePackFormat } from "../versions/registry";

/** Resource-pack major format for a version, from the version registry. Throws for an unknown/unverified version (never guesses). */
export function packFormatFor(mc: string): number {
  const r = resourcePackFormat(mc);
  if (!r.ok) throw new Error(r.error);
  return r.format.major;
}

export type BuiltPack = { packFormat: number; packClientVerified: boolean; zip: Buffer; sha1: string; bytes: number; files: string[]; textures: { name: string; model: string }[] };

export function buildPack(opts: { namespace: string; description: string; mcVersion: string; textures: unknown[]; allowPreview?: boolean }): { ok: true; pack: BuiltPack } | { ok: false; error: string } {
  if (!/^[a-z][a-z0-9_]{1,30}$/.test(opts.namespace)) return { ok: false, error: "namespace must be lowercase letters, digits and underscores" };
  if (opts.textures.length === 0 || opts.textures.length > 24) return { ok: false, error: "a pack needs 1-24 textures" };
  const specs: TextureSpec[] = [];
  for (const [i, t] of opts.textures.entries()) { const c = checkSpec(t); if (!c.ok) return { ok: false, error: `texture ${i + 1}: ${c.error}` }; if (specs.some((s) => s.name === c.spec.name)) return { ok: false, error: `duplicate texture name ${c.spec.name}` }; specs.push(c.spec); }
  const ver = getVersion(opts.mcVersion);
  if (ver && ver.status === "preview" && !opts.allowPreview) return { ok: false, error: `${opts.mcVersion} is a preview version: its resource packs are not verified in a real client yet` };
  const pf = resourcePackFormat(opts.mcVersion, { needsItemModels: true });
  if (!pf.ok) return { ok: false, error: pf.error };
  const fmt = pf.format.major;
  const files: { path: string; data: Buffer }[] = [
    { path: "pack.mcmeta", data: Buffer.from(JSON.stringify({ pack: { pack_format: fmt, supported_formats: { min_inclusive: 46, max_inclusive: 999 }, min_format: 46, max_format: 999, description: opts.description.slice(0, 100) } }, null, 2)) },
  ];
  const ns = opts.namespace;
  for (const s of specs) {
    files.push({ path: `assets/${ns}/textures/item/${s.name}.png`, data: encodePng(render(s)) });
    files.push({ path: `assets/${ns}/models/item/${s.name}.json`, data: Buffer.from(JSON.stringify({ parent: "minecraft:item/handheld", textures: { layer0: `${ns}:item/${s.name}` } }, null, 2)) });
    files.push({ path: `assets/${ns}/items/${s.name}.json`, data: Buffer.from(JSON.stringify({ model: { type: "minecraft:model", model: `${ns}:item/${s.name}` } }, null, 2)) });
  }
  const z = zip(files);
  return { ok: true, pack: { packFormat: fmt, packClientVerified: pf.clientVerified, zip: z, sha1: createHash("sha1").update(z).digest("hex"), bytes: z.length, files: files.map((f) => f.path).sort(), textures: specs.map((s) => ({ name: s.name, model: `${ns}:${s.name}` })) } };
}
