// Minimal AWS Signature Version 4 (header auth) with node:crypto. Enough for S3-compatible object storage
// (path-style requests). Tested against AWS's published test vectors (test/cyrus-packhost.test.ts).
import { createHash, createHmac } from "node:crypto";

export type SigV4Credentials = { accessKeyId: string; secretAccessKey: string; sessionToken?: string };
export type SigV4Request = {
  method: string;
  url: string;
  /** Headers to sign (host is added from the URL when missing). Names are case-insensitive. */
  headers?: Record<string, string>;
  /** Hex sha256 of the body, or "UNSIGNED-PAYLOAD". Defaults to the hash of an empty body. */
  payloadHash?: string;
  region: string;
  service: string;
  /** Signing time (defaults to now). */
  date?: Date;
};

export const EMPTY_SHA256 = "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855";
export const sha256Hex = (data: Buffer | string) => createHash("sha256").update(data).digest("hex");
const hmac = (key: Buffer | string, data: string) => createHmac("sha256", key).update(data, "utf8").digest();

/** RFC 3986 encoding as SigV4 wants it (unreserved: A-Z a-z 0-9 - _ . ~). */
export function uriEncode(s: string, keepSlash = false): string {
  let out = "";
  for (const ch of Buffer.from(s, "utf8")) {
    const c = String.fromCharCode(ch);
    if (/[A-Za-z0-9\-_.~]/.test(c) || (keepSlash && c === "/")) out += c;
    else out += "%" + ch.toString(16).toUpperCase().padStart(2, "0");
