export function validateCatalog(raw: unknown): { ok: true; entries: CatalogEntry[] } | { ok: false; errors: string[] } {
  const errors: string[] = [];
  const d = raw as { schema?: unknown; entries?: unknown };
  if (!d || d.schema !== 1 || !Array.isArray(d.entries)) return { ok: false, errors: ["catalog must be { schema: 1, entries: [...] }"] };
  const seen = new Set<string>();
