    if (!/^[A-Za-z0-9_-]{1,64}$/.test(String(e.pluginName ?? ""))) errors.push(`${at}.pluginName must be a plugin.yml name`);
    if (!(SOURCES as readonly string[]).includes(String(e.source))) errors.push(`${at}.source must be one of ${SOURCES.join(", ")}`);
    if (typeof e.sourceRef !== "string" || !e.sourceRef) errors.push(`${at}.sourceRef is required`);
    if (!SHA256_RE.test(String(e.sha256 ?? ""))) errors.push(`${at}.sha256 must be a sha256 hex digest`);
    if (typeof e.artifact !== "string" || !/^[A-Za-z0-9][A-Za-z0-9._/-]{0,199}$/.test(e.artifact) || e.artifact.split("/").includes("..")) errors.push(`${at}.artifact must be a relative path`);
