// Ref-counting rules for managed plugins (pure). A managed plugin is on a server while at least one dependent
// (a Cyrus project or mod) needs it, at the version pinned for the server's Minecraft family.
import type { CatalogEntry } from "./catalog";

export const DEPENDENT_RE = /^(project|mod):[A-Za-z0-9_-]{1,64}$/;
export type ManagedStatus = "installing" | "installed" | "failed" | "removing" | "removed";
export type ManagedRow = { status: ManagedStatus; version: string | null; sha256: string | null; family: string; dependents: string[] };

export type EnsurePlan =
  | { kind: "install" | "upgrade"; dependents: string[] }
  | { kind: "addRef" | "noop"; dependents: string[] }
  | { kind: "busy"; dependents: string[] };
export type ReleasePlan = { kind: "remove" | "decRef" | "noop" | "busy"; dependents: string[] };

const withDep = (deps: string[], d: string) => [...new Set([...deps, d])].sort();

export function planEnsure(row: ManagedRow | null, dependent: string, pin: CatalogEntry): EnsurePlan {
  if (!DEPENDENT_RE.test(dependent)) throw new Error(`bad dependent id ${dependent}`);
  const current = row?.dependents ?? [];
  if (row && (row.status === "installing" || row.status === "removing")) return { kind: "busy", dependents: current };
  const deps = withDep(row && row.status !== "removed" ? current : [], dependent);
  if (!row || row.status === "removed" || row.status === "failed" || !row.version) return { kind: "install", dependents: deps };
  if (row.version !== pin.version || row.sha256 !== pin.sha256 || row.family !== pin.family) return { kind: "upgrade", dependents: deps };
  return current.includes(dependent) ? { kind: "noop", dependents: current } : { kind: "addRef", dependents: deps };
}

export function planRelease(row: ManagedRow | null, dependent: string): ReleasePlan {
  if (!DEPENDENT_RE.test(dependent)) throw new Error(`bad dependent id ${dependent}`);
  if (!row || row.status === "removed") return { kind: "noop", dependents: [] };
  if (row.status === "installing" || row.status === "removing") return { kind: "busy", dependents: row.dependents };
  // A failed removal left nothing depending on it: releasing again retries the removal.
  if (row.status === "failed" && row.dependents.length === 0) return { kind: "remove", dependents: [] };
  if (!row.dependents.includes(dependent)) return { kind: "noop", dependents: row.dependents };
  const rest = row.dependents.filter((d) => d !== dependent);
  return rest.length ? { kind: "decRef", dependents: rest } : { kind: "remove", dependents: [] };
}

/** The customer may remove a managed plugin only when nothing depends on it. */
export function userRemovable(row: ManagedRow | null): { ok: true } | { ok: false; dependents: string[] } {
  if (!row || row.dependents.length === 0) return { ok: true };
  return { ok: false, dependents: row.dependents };
}
