// ensureManagedPlugin / releaseManagedPlugin: the only writer of CyrusServerManagedPlugin. Server only.
// Each call: (1) a short transaction locks the server's row (FOR UPDATE), plans with ./refs and records intent;
// (2) the injected installer runs OUTSIDE any transaction (it talks to the server); (3) a second transaction
// records the outcome. A row in installing/removing makes concurrent callers get `busy` (retry later).
import type { Prisma, PrismaClient } from "@prisma/client";
import { pinFor, type CatalogEntry } from "./catalog";
import type { ManagedInstaller } from "./installer";
import { DEPENDENT_RE, planEnsure, planRelease, userRemovable, type ManagedRow, type ManagedStatus } from "./refs";

type Db = Pick<PrismaClient, "$transaction" | "cyrusServerManagedPlugin">;
type Tx = Prisma.TransactionClient;
export type ManagedDeps = { db: Db; installer: ManagedInstaller; catalog: CatalogEntry[] };

export type EnsureResult =
  | { ok: true; action: "installed" | "upgraded" | "ref_added" | "already"; version: string; refCount: number }
  | { ok: false; code: "bad_input" | "unknown_version" | "unknown_plugin" | "no_pin" | "java_too_old" | "busy" | "install_failed"; error: string };
export type ReleaseResult =
  | { ok: true; action: "removed" | "ref_dropped" | "not_held"; refCount: number }
  | { ok: false; code: "bad_input" | "busy" | "remove_failed"; error: string };

type RowRec = { id: string; status: string; version: string | null; sha256: string | null; family: string; dependents: unknown; refCount: number };
const toRow = (r: RowRec): ManagedRow => ({
  status: r.status as ManagedStatus, version: r.version, sha256: r.sha256, family: r.family,
  dependents: Array.isArray(r.dependents) ? (r.dependents as unknown[]).filter((d): d is string => typeof d === "string").sort() : [],
});

/** Get-or-create the row and lock it for this transaction. A fresh row starts as `removed` with no dependents. */
async function lockRow(tx: Tx, serverId: string, key: string, family: string): Promise<RowRec> {
  try {
    await tx.cyrusServerManagedPlugin.upsert({ where: { serverId_key: { serverId, key } }, create: { serverId, key, family, status: "removed", dependents: [], refCount: 0 }, update: {} });
  } catch (e) {
    if ((e as { code?: string }).code !== "P2002") throw e; // a concurrent create won; the row exists now
  }
  const rows = await tx.$queryRaw<RowRec[]>`SELECT "id","status","version","sha256","family","dependents","refCount" FROM "CyrusServerManagedPlugin" WHERE "serverId" = ${serverId} AND "key" = ${key} FOR UPDATE`;
  if (!rows[0]) throw new Error("managed plugin row vanished");
  return rows[0];
}

export async function ensureManagedPlugin(deps: ManagedDeps, args: { serverId: string; key: string; mcVersion: string; dependent: string }): Promise<EnsureResult> {
  if (!args.serverId || !DEPENDENT_RE.test(args.dependent)) return { ok: false, code: "bad_input", error: "serverId and a dependent id (project:<id> or mod:<id>) are required" };
  const pin = pinFor(deps.catalog, args.key, args.mcVersion);
  if (!pin.ok) return { ok: false, code: pin.code, error: pin.error };
  const entry = pin.entry;

  const step1 = await deps.db.$transaction(async (tx) => {
    const rec = await lockRow(tx, args.serverId, args.key, entry.family);
    const row = toRow(rec);
    const plan = planEnsure(rec.status === "removed" && !row.dependents.length && !rec.version ? null : row, args.dependent, entry);
    if (plan.kind === "busy") return { plan, rec, prev: row };
    const data: Prisma.CyrusServerManagedPluginUpdateInput = { dependents: plan.dependents, refCount: plan.dependents.length };
    if (plan.kind === "install" || plan.kind === "upgrade") Object.assign(data, { status: "installing", family: entry.family, error: null });
    await tx.cyrusServerManagedPlugin.update({ where: { id: rec.id }, data });
    return { plan, rec, prev: row };
  });
  const { plan, rec, prev } = step1;
  if (plan.kind === "busy") return { ok: false, code: "busy", error: `${entry.displayName} is being changed on this server right now; try again shortly` };
  if (plan.kind === "noop" || plan.kind === "addRef") return { ok: true, action: plan.kind === "noop" ? "already" : "ref_added", version: prev.version ?? entry.version, refCount: plan.dependents.length };

  let out: Awaited<ReturnType<ManagedInstaller["install"]>>;
  try {
    out = await deps.installer.install({ serverId: args.serverId, entry, previousVersion: prev.status === "installed" || prev.status === "failed" ? prev.version : null });
  } catch (e) {
    out = { ok: false, error: (e as Error).message || "installer threw" };
  }
  if (out.ok) {
    await deps.db.cyrusServerManagedPlugin.update({ where: { id: rec.id }, data: { status: "installed", version: out.version, sha256: out.sha256, installedAt: new Date(), error: null } });
    return { ok: true, action: plan.kind === "upgrade" ? "upgraded" : "installed", version: out.version, refCount: plan.dependents.length };
  }
  // The dependent stays recorded (desired state): the next ensure retries the install.
  await deps.db.cyrusServerManagedPlugin.update({ where: { id: rec.id }, data: { status: "failed", error: out.error.slice(0, 500) } });
  return { ok: false, code: "install_failed", error: out.error };
}

export async function releaseManagedPlugin(deps: ManagedDeps, args: { serverId: string; key: string; dependent: string }): Promise<ReleaseResult> {
  if (!args.serverId || !DEPENDENT_RE.test(args.dependent)) return { ok: false, code: "bad_input", error: "serverId and a dependent id are required" };
  const existing = await deps.db.cyrusServerManagedPlugin.findUnique({ where: { serverId_key: { serverId: args.serverId, key: args.key } } });
  if (!existing) return { ok: true, action: "not_held", refCount: 0 };
  const pluginName = deps.catalog.find((e) => e.key === args.key)?.pluginName ?? null;

  const step1 = await deps.db.$transaction(async (tx) => {
    const rec = await lockRow(tx, args.serverId, args.key, existing.family);
    const plan = planRelease(toRow(rec), args.dependent);
    if (plan.kind === "busy" || plan.kind === "noop") return { plan, rec };
    const data: Prisma.CyrusServerManagedPluginUpdateInput = { dependents: plan.dependents, refCount: plan.dependents.length };
    if (plan.kind === "remove") Object.assign(data, { status: "removing", error: null });
    await tx.cyrusServerManagedPlugin.update({ where: { id: rec.id }, data });
    return { plan, rec };
  });
  const { plan, rec } = step1;
  if (plan.kind === "busy") return { ok: false, code: "busy", error: "this managed plugin is being changed right now; try again shortly" };
  if (plan.kind === "noop") return { ok: true, action: "not_held", refCount: plan.dependents.length };
  if (plan.kind === "decRef") return { ok: true, action: "ref_dropped", refCount: plan.dependents.length };

  let out: Awaited<ReturnType<ManagedInstaller["remove"]>>;
  try {
    out = await deps.installer.remove({ serverId: args.serverId, key: args.key, pluginName, version: rec.version });
  } catch (e) {
    out = { ok: false, error: (e as Error).message || "installer threw" };
  }
  if (out.ok) {
    await deps.db.cyrusServerManagedPlugin.update({ where: { id: rec.id }, data: { status: "removed", version: null, sha256: null, installedAt: null, error: null } });
    return { ok: true, action: "removed", refCount: 0 };
  }
  await deps.db.cyrusServerManagedPlugin.update({ where: { id: rec.id }, data: { status: "failed", error: out.error.slice(0, 500) } });
  return { ok: false, code: "remove_failed", error: out.error };
}

/** Guard for any customer-facing removal path (Mods tab etc.): refuse while something depends on the plugin. */
export async function canUserRemove(db: Pick<PrismaClient, "cyrusServerManagedPlugin">, serverId: string, key: string) {
  const r = await db.cyrusServerManagedPlugin.findUnique({ where: { serverId_key: { serverId, key } } });
  return userRemovable(r ? toRow(r) : null);
}
