import java.util.regex.Pattern;

/**
 * packs.json, written by Nxeon. Same rules as lib/cyrus/packhost/loader-config.ts validateLoaderConfig:
 * any problem rejects the WHOLE file, so a broken config never sends anything.
 */
final class PackConfig {
    static final int SCHEMA = 1;
    static final int MAX_PACKS = 16;
    static final int MAX_PROMPT = 300;
    static final int MAX_URL = 1000;
    private static final Pattern UUID_RE = Pattern.compile("^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$");
    private static final Pattern SHA1_RE = Pattern.compile("^[0-9a-f]{40}$");

    static final class Pack {
        final UUID id;
        final String url;
        final String sha1;
        final byte[] hash;
        final String prompt;
        final boolean required;

        Pack(UUID id, String url, String sha1, String prompt, boolean required) {
            this.id = id;
            this.url = url;
            this.sha1 = sha1;
            this.hash = hex(sha1);
            this.prompt = prompt;
            this.required = required;
        }
    }

    final List<Pack> packs;

    private PackConfig(List<Pack> packs) {
        this.packs = Collections.unmodifiableList(packs);
    }

    static PackConfig empty() {
        return new PackConfig(new ArrayList<>());
    }

    /** Parse or throw IllegalArgumentException with every problem found. */
    static PackConfig parse(String text) {
        List<String> errors = new ArrayList<>();
        JsonElement root;
        try {
            root = JsonParser.parseString(text);
        } catch (RuntimeException e) {
            throw new IllegalArgumentException("not valid JSON: " + e.getMessage());
        }
        if (!root.isJsonObject()) throw new IllegalArgumentException("config must be a JSON object");
        JsonObject o = root.getAsJsonObject();
        if (!o.has("schema") || !o.get("schema").isJsonPrimitive() || !o.get("schema").getAsJsonPrimitive().isNumber() || o.get("schema").getAsInt() != SCHEMA) {
            errors.add("schema must be " + SCHEMA);
        }
        if (!o.has("packs") || !o.get("packs").isJsonArray()) {
            errors.add("packs must be an array");
            throw new IllegalArgumentException(String.join("; ", errors));
        }
        JsonArray arr = o.getAsJsonArray("packs");
        if (arr.size() > MAX_PACKS) errors.add("at most " + MAX_PACKS + " packs");
        List<Pack> out = new ArrayList<>();
        Set<String> ids = new HashSet<>();
        for (int i = 0; i < arr.size(); i++) {
            String at = "packs[" + i + "]";
            if (!arr.get(i).isJsonObject()) { errors.add(at + " must be an object"); continue; }
            JsonObject p = arr.get(i).getAsJsonObject();
            String id = str(p, "id");
            String url = str(p, "url");
            String sha1 = str(p, "sha1");
            boolean idOk = id != null && UUID_RE.matcher(id).matches();
            if (!idOk) errors.add(at + ".id must be a lower-case UUID");
            else if (!ids.add(id)) errors.add(at + ".id " + id + " appears twice");
            if (!validUrl(url)) errors.add(at + ".url must be an http(s) URL of at most " + MAX_URL + " chars");
            boolean shaOk = sha1 != null && SHA1_RE.matcher(sha1).matches();
            if (!shaOk) errors.add(at + ".sha1 must be 40 lower-case hex chars");
            String prompt = null;
            if (p.has("prompt") && !p.get("prompt").isJsonNull()) {
                prompt = str(p, "prompt");
                if (prompt == null || prompt.length() > MAX_PROMPT) errors.add(at + ".prompt must be a string of at most " + MAX_PROMPT + " chars");
            }
            Boolean required = null;
            if (p.has("required") && p.get("required").isJsonPrimitive() && p.get("required").getAsJsonPrimitive().isBoolean()) required = p.get("required").getAsBoolean();
            if (required == null) errors.add(at + ".required must be true or false");
            if (idOk && shaOk && required != null && validUrl(url) && (prompt == null || prompt.length() <= MAX_PROMPT)) {
                out.add(new Pack(UUID.fromString(id), url, sha1, prompt, required));
            }
        }
        if (!errors.isEmpty()) throw new IllegalArgumentException(String.join("; ", errors));
        return new PackConfig(out);
    }

    private static String str(JsonObject o, String k) {
        JsonElement e = o.get(k);
        return e != null && e.isJsonPrimitive() && e.getAsJsonPrimitive().isString() ? e.getAsString() : null;
    }

    private static boolean validUrl(String url) {
        if (url == null || url.isEmpty() || url.length() > MAX_URL) return false;
        try {
            URI u = new URI(url);
            String s = u.getScheme() == null ? "" : u.getScheme().toLowerCase(Locale.ROOT);
            return (s.equals("https") || s.equals("http")) && u.getHost() != null && u.getUserInfo() == null;
        } catch (Exception e) {
            return false;
        }
    }

    private static byte[] hex(String s) {
        byte[] b = new byte[s.length() / 2];
        for (int i = 0; i < b.length; i++) b[i] = (byte) Integer.parseInt(s.substring(i * 2, i * 2 + 2), 16);
        return b;
    }
}
