 * Fail safe: a missing, empty or invalid packs.json sends nothing. The file is re-read on /nxpacks reload and when
 * it changes on disk (checked every 10 s), without a restart.
 */
public final class NxeonPackLoader extends JavaPlugin implements Listener, TabExecutor {
    private static final long POLL_TICKS = 200L; // 10 s
    private static final long FLUSH_TICKS = 600L; // 30 s

    private volatile PackConfig active = PackConfig.empty();
    private volatile String lastError = null;
    private volatile String loadedAt = null;
    private long seenMtime = -1L;
    private long seenSize = -1L;
    private final Map<String, Map<String, Integer>> statusCounts = new TreeMap<>();
    private final Map<String, Integer> sentCounts = new TreeMap<>();
    private String telemetrySince;
    private boolean dirty = false;
    private boolean geyser = false;
    private boolean floodgate = false;

    private File packsFile() { return new File(getDataFolder(), "packs.json"); }
    private File telemetryFile() { return new File(getDataFolder(), "telemetry.json"); }

    @Override
    public void onEnable() {
        if (!getDataFolder().isDirectory() && !getDataFolder().mkdirs()) getLogger().warning("could not create " + getDataFolder());
        geyser = getServer().getPluginManager().getPlugin("Geyser-Spigot") != null;
