cd /tank/dev-worktrees/cyrus-r0 && cat > test/cyrus-packloader-real.ts <<'EOF'
// REAL Test Flight runs of the Nxeon Pack Loader on node-2 (not part of the unit suite: boots real Paper servers).
//   tsx test/cyrus-packloader-real.ts [v12111|v262|badboot|nofile|all] [--out file.json]
// The jar is built on node-2 with services/modbuilder/tools/packloader/build.sh and copied to
// /tank/nxeon-build/tmp/testflight/inbox/fx/NxeonPackLoader-0.1.0.jar (see docs "Cyrus pack delivery (R0)").
// The packs.json files are produced by the TypeScript side (applyPackChange + serializeLoaderConfig), so these
// flights also check that the plugin accepts exactly what Nxeon writes. NO client connects: pack sending,
// accept/decline telemetry and actual pack loading are NOT exercised here.
import { writeFileSync } from "node:fs";
import { runTestFlight, type RunResult } from "../lib/cyrus/testflight/client";
import { describe } from "../lib/cyrus/testflight/summary";
import type { RconCheck, TestFlightSpec } from "../lib/cyrus/testflight/types";
import { applyPackChange, LOADER_CONFIG_PATH, serializeLoaderConfig, type LoaderConfig } from "../lib/cyrus/packhost/loader-config";
import { publicPackUrl } from "../lib/cyrus/packhost/types";

const JAR = "/tank/nxeon-build/tmp/testflight/inbox/fx/NxeonPackLoader-0.1.0.jar";
const urlFor = (sha1: string) => publicPackUrl("https://packs.example.invalid", sha1);
const SHA_A = "a".repeat(40), SHA_B = "b".repeat(40), SHA_C = "c".repeat(40);

function cfg(...changes: Parameters<typeof applyPackChange>[1][]): LoaderConfig {
  let c: LoaderConfig | null = null;
  for (const ch of changes) {
    const r = applyPackChange(c, ch, { urlFor });
    if (!r.ok) throw new Error(r.error);
    c = r.config;
  }
  return c!;
}
const two = cfg(
  { op: "upsert", namespace: "nx_abcd1234", role: "main", sha1: SHA_A, prompt: "Textures for Coin Shop", required: true },
  { op: "upsert", namespace: "nx_efgh5678", role: "main", sha1: SHA_B, required: false },
);
const [idA, idB] = two.packs.map((p) => p.id);
const one = cfg({ op: "upsert", namespace: "nx_abcd1234", role: "main", sha1: SHA_C, prompt: "Textures for Coin Shop", required: true });
const file = (c: LoaderConfig | string) => ({ path: LOADER_CONFIG_PATH, content: typeof c === "string" ? c : serializeLoaderConfig(c) });
const BAD_SHA = JSON.stringify({ schema: 1, packs: [{ id: idA, url: urlFor(SHA_A), sha1: "XYZ", required: true }, { id: idA, url: urlFor(SHA_B), sha1: SHA_B, required: false }] });

const reloadCycle: RconCheck[] = [
  { id: "list-two", command: "nxpacks list", expect: ["2 pack(s)", idA, idB, `sha1=${SHA_A}`, "required=true", "required=false"], expectNot: ["REJECTED"] },
  { id: "status-ok", command: "nxpacks status", expect: ["packs=2", "config=ok", "geyser=false", "floodgate=false"] },
  { id: "reload-one", command: "nxpacks reload", writeFile: file(one), expect: ["packs.json loaded (command): 1 pack(s)"] },
  { id: "list-one", command: "nxpacks list", expect: ["1 pack(s)", idA, `sha1=${SHA_C}`], expectNot: [idB, "REJECTED"] },
  { id: "reload-bad-fields", command: "nxpacks reload", writeFile: file(BAD_SHA), expect: ["packs.json rejected", "sha1 must be 40 lower-case hex chars", "appears twice", "sending no packs"] },
  { id: "list-after-bad", command: "nxpacks list", expect: ["0 pack(s)", "REJECTED"], expectNot: [idA] },
  { id: "reload-not-json", command: "nxpacks reload", writeFile: file("{ this is not json"), expect: ["packs.json rejected", "not valid JSON"] },
  { id: "watch-picks-up-fix", command: "nxpacks list", writeFile: file(two), waitMs: 12000, expect: ["2 pack(s)", idA, idB], expectNot: ["REJECTED"] },
  { id: "usage", command: "nxpacks bogus", expect: ["Usage: /nxpacks <list|reload|status>"] },
  { id: "plugins-listed", command: "plugins", expect: ["NxeonPackLoader"] },
];

const specs: Record<string, TestFlightSpec> = {
  v12111: { version: "1.21.11", plugins: [{ remotePath: JAR }], files: [file(two)], rcon: reloadCycle },
  v262: { version: "26.2", plugins: [{ remotePath: JAR }], files: [file(two)], rcon: reloadCycle },
  badboot: {
    version: "26.2", plugins: [{ remotePath: JAR }], files: [file(BAD_SHA)],
    rcon: [
      { id: "list-rejected", command: "nxpacks list", expect: ["0 pack(s)", "REJECTED", "sha1 must be"] },
      { id: "status-rejected", command: "nxpacks status", expect: ["packs=0", "config=rejected"] },
      { id: "server-still-works", command: "help", expect: ["Help"] },
    ],
  },
  nofile: {
    version: "1.21.11", plugins: [{ remotePath: JAR }],
    rcon: [
      { id: "list-none", command: "nxpacks list", expect: ["0 pack(s)"], expectNot: ["REJECTED"] },
      { id: "reload-created", command: "nxpacks reload", writeFile: file(one), expect: ["1 pack(s)"] },
    ],
  },
};

const brief = (name: string, r: RunResult) => ({
  name, version: r.report.version, status: r.report.status, overall: r.summary.overall, success: r.summary.success,
  bootMs: r.report.bootMs, peakRssKb: r.report.peakRssKb, timings: r.report.timings,
  checks: r.report.checks.map((c) => ({ id: c.id, status: c.status, evidence: c.evidence })),
  line: describe(r.summary), notes: r.report.notes, artifacts: r.report.artifacts, engine: r.report.engine,
});

async function main() {
  const which = process.argv[2] ?? "all";
  const outIdx = process.argv.indexOf("--out");
  const names = which === "all" ? ["v12111", "v262", "badboot", "nofile"] : [which];
  const out: unknown[] = [];
  for (const n of names) { // strictly one at a time (node-2 rule)
    const r = await runTestFlight(specs[n]);
    out.push(brief(n, r));
    console.log(`${n}: ${describe(r.summary)}`);
  }
  if (outIdx > 0) writeFileSync(process.argv[outIdx + 1], JSON.stringify(out, null, 1));
  else console.log(JSON.stringify(out, null, 1));
}
