// Cyrus pack hosting + pack install logic (R0): pure tests, the local disk store on a temp dir, the S3 store with a
// fake fetch, and the SigV4 signer against AWS's published test vectors. No network, no cloud bucket, no DB.
//   tsx --test test/cyrus-packhost.test.ts
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import { mkdtempSync, rmSync, utimesSync } from "node:fs";
import { tmpdir } from "node:os";
import path from "node:path";
import { signV4, signingKey, uriEncode, EMPTY_SHA256, sha256Hex } from "../lib/cyrus/packhost/sigv4";
import { LocalDiskStore } from "../lib/cyrus/packhost/local";
import { S3Store, parseListObjects } from "../lib/cyrus/packhost/s3";
import { selectPackStore, maxPackBytes } from "../lib/cyrus/packhost/config";
import { publishPack, planPackGc, runPackGc } from "../lib/cyrus/packhost/publish";
import { inspectPackZip } from "../lib/cyrus/packhost/zipcheck";
import { IMMUTABLE_CACHE_CONTROL, packKey, parsePackFile, publicPackUrl, DEFAULT_MAX_PACK_BYTES } from "../lib/cyrus/packhost/types";
import {
  applyPackChange, packIdFor, referencedSha1s, serializeLoaderConfig, serverPropertiesFallback, uuidV5, validateLoaderConfig, MAX_PACKS, type LoaderConfig,
} from "../lib/cyrus/packhost/loader-config";
import { zip } from "../lib/cyrus/textures/zip";

const sha1 = (b: Buffer) => createHash("sha1").update(b).digest("hex");
const pack = (desc = "x") => zip([{ path: "pack.mcmeta", data: Buffer.from(JSON.stringify({ pack: { pack_format: 46, description: desc } })) }, { path: "assets/nx_a/x.txt", data: Buffer.from(desc) }]);
const tmp = () => mkdtempSync(path.join(tmpdir(), "cyrus-packhost-"));

describe("SigV4 signer (AWS published test vectors)", () => {
  const suite = { accessKeyId: "AKIDEXAMPLE", secretAccessKey: "wJalrXUtnFEMI/K7MDENG+bPxRfiCYEXAMPLEKEY" };
  const date = new Date("2015-08-30T12:36:00Z");
  it("derives the documented signing key (iam, 20120215)", () => {
    assert.equal(signingKey("wJalrXUtnFEMI/K7MDENG+bPxRfiCYEXAMPLEKEY", "20120215", "us-east-1", "iam").toString("hex"), "f4780e2d9f65fa895f9c67b32ce1baf0b0d8a43505a000a1a9e090d414db404d");
  });
  it("get-vanilla", () => {
    const s = signV4({ method: "GET", url: "https://example.amazonaws.com/", region: "us-east-1", service: "service", date }, suite);
    assert.equal(s.canonicalRequest, `GET\n/\n\nhost:example.amazonaws.com\nx-amz-date:20150830T123600Z\n\nhost;x-amz-date\n${EMPTY_SHA256}`);
    assert.equal(s.signature, "5fa00fa31553b73ebf1942676e86291e8372ff2a2260956d9b8aae1d763fbf31");
    assert.equal(s.authorization, "AWS4-HMAC-SHA256 Credential=AKIDEXAMPLE/20150830/us-east-1/service/aws4_request, SignedHeaders=host;x-amz-date, Signature=5fa00fa31553b73ebf1942676e86291e8372ff2a2260956d9b8aae1d763fbf31");
  });
  it("get-vanilla-query-order-key-case (query sorted)", () => {
    const s = signV4({ method: "GET", url: "https://example.amazonaws.com/?Param2=value2&Param1=value1", region: "us-east-1", service: "service", date }, suite);
    assert.equal(s.signature, "b97d918cfa904a5beff61c982a1b6f458b799221646efd99d3219ec94cdf2500");
  });
  it("post-vanilla", () => {
    const s = signV4({ method: "POST", url: "https://example.amazonaws.com/", region: "us-east-1", service: "service", date }, suite);
    assert.equal(s.signature, "5da7c1a2acd57cee7505fc6676e4e544621c30862966e37dddb68e92efbe5d6b");
  });
  const s3c = { accessKeyId: "[REDACTED]", secretAccessKey: "wJalrXUtnFEMI/K7MDENG/bPxRfiCYEXAMPLEKEY" };
  const d13 = new Date("2013-05-24T00:00:00Z");
  it("S3 docs example: GET object with Range", () => {
    const s = signV4({ method: "GET", url: "https://examplebucket.s3.amazonaws.com/test.txt", headers: { Range: "bytes=0-9" }, region: "us-east-1", service: "s3", date: d13 }, s3c);
    assert.equal(s.signature, "f0e8bdb87c964420e857bd35b5d6ed310bd44f0170aba48dd91039c6036bdb41");
  });
  it("S3 docs example: PUT object (encoded key, signed body)", () => {
    const body = Buffer.from("Welcome to Amazon S3.");
    assert.equal(sha256Hex(body), "44ce7dd67c959e0d3524ffac1771dfbba87d2b6b4b4e99e42034a8b803f8b072");
    const s = signV4({ method: "PUT", url: "https://examplebucket.s3.amazonaws.com/test$file.text", headers: { Date: "Fri, 24 May 2013 00:00:00 GMT", "x-amz-storage-class": "REDUCED_REDUNDANCY" }, payloadHash: sha256Hex(body), region: "us-east-1", service: "s3", date: d13 }, s3c);
    assert.match(s.canonicalRequest, /^PUT\n\/test%24file\.text\n/);
    assert.equal(s.signature, "98ad721746da40c64f1a55b78f14c238d841ea1380cd77a1b5971af0ece108bd");
  });
  it("S3 docs examples: GET ?lifecycle and ListObjects ?max-keys=2&prefix=J", () => {
    const a = signV4({ method: "GET", url: "https://examplebucket.s3.amazonaws.com/?lifecycle", region: "us-east-1", service: "s3", date: d13 }, s3c);
    assert.equal(a.signature, "fea454ca298b7da1c68078a5d1bdbfbbe0d65c699e0f91ac7a200a0136783543");
    const b = signV4({ method: "GET", url: "https://examplebucket.s3.amazonaws.com/?max-keys=2&prefix=J", region: "us-east-1", service: "s3", date: d13 }, s3c);
    assert.equal(b.signature, "34b48302e7b5fa45bde8084f4b7868a86f0a534bc59db6670ed5711ef69dc6f7");
  });
  it("uriEncode is RFC 3986 (space %20, slash kept only when asked, utf-8 bytes)", () => {
    assert.equal(uriEncode("a b/c~*"), "a%20b%2Fc~%2A");
    assert.equal(uriEncode("a b/c", true), "a%20b/c");
    assert.equal(uriEncode("é"), "%C3%A9");
  });
});

describe("keys and public URLs", () => {
  const s = "0123456789abcdef0123456789abcdef01234567";
  it("content-addressed key /p/<sha1>.zip on the configured base, never anything else", () => {
    assert.equal(packKey(s), `p/${s}.zip`);
    assert.equal(publicPackUrl("https://packs.example.com", s), `https://packs.example.com/p/${s}.zip`);
    assert.equal(publicPackUrl("https://cdn.example.com/mc/", s), `https://cdn.example.com/mc/p/${s}.zip`);
    assert.throws(() => packKey("../etc"));
    assert.throws(() => publicPackUrl("ftp://x", s));
    assert.throws(() => publicPackUrl("https://u:p@x.com", s));
    assert.throws(() => publicPackUrl("https://x.com/?a=1", s));
    assert.equal(parsePackFile(`${s}.zip`), s);
    assert.equal(parsePackFile(`${s.toUpperCase()}.zip`), null);
    assert.equal(parsePackFile(`${s}.zip.part`), null);
    assert.equal(IMMUTABLE_CACHE_CONTROL, "public, max-age=31536000, immutable");
  });
});

describe("zip check", () => {
  it("accepts a pack with pack.mcmeta and refuses junk, missing mcmeta and unsafe names", () => {
    assert.equal(inspectPackZip(pack()).ok, true);
    assert.equal(inspectPackZip(Buffer.from("hello")).ok, false);
    assert.match((inspectPackZip(zip([{ path: "a.txt", data: Buffer.from("a") }])) as { error: string }).error, /pack\.mcmeta/);
    assert.match((inspectPackZip(zip([{ path: "pack.mcmeta", data: Buffer.from("{}") }, { path: "../evil", data: Buffer.from("a") }])) as { error: string }).error, /unsafe/);
  });
});

describe("LocalDiskStore + publish + GC", () => {
  it("put is content-addressed, verified and idempotent; list/exists/delete work", async () => {
    const dir = tmp();
    try {
      const st = new LocalDiskStore(dir, "http://localhost:3000");
      const z = pack("one");
      const h = sha1(z);
      await assert.rejects(st.put("f".repeat(40), z), /does not match/);
      assert.deepEqual(await st.put(h, z), { sha1: h, key: `p/${h}.zip`, size: z.length, created: true });
      assert.equal((await st.put(h, z)).created, false);
      assert.equal(await st.exists(h), true);
      assert.deepEqual((await st.read(h))!, z);
      assert.equal(st.urlFor(h), `http://localhost:3000/p/${h}.zip`);
      assert.deepEqual((await st.list()).map((o) => o.sha1), [h]);
      assert.equal(await st.delete(h), true);
      assert.equal(await st.exists(h), false);
      assert.equal(await st.delete(h), false);
    } finally { rmSync(dir, { recursive: true, force: true }); }
  });
  it("publishPack enforces the size cap and the zip check", async () => {
    const dir = tmp();
    try {
      const st = new LocalDiskStore(dir, "https://packs.example.com");
      const z = pack("cap");
      const ok = await publishPack(st, z, { maxBytes: DEFAULT_MAX_PACK_BYTES });
      assert.ok(ok.ok && ok.url === `https://packs.example.com/p/${sha1(z)}.zip` && ok.created);
      assert.deepEqual(await publishPack(st, z, { maxBytes: z.length - 1 }), { ok: false, code: "too_large", error: `the pack is ${z.length} bytes; the limit is ${z.length - 1}` });
      assert.equal((await publishPack(st, Buffer.alloc(0), { maxBytes: 10 })).ok, false);
      assert.equal((await publishPack(st, Buffer.from("PK\x03\x04garbage"), { maxBytes: 1000 }) as { code: string }).code, "bad_zip");
    } finally { rmSync(dir, { recursive: true, force: true }); }
  });
  it("GC deletes only unreferenced objects older than the retention, dry run by default", async () => {
    const dir = tmp();
    try {
      const st = new LocalDiskStore(dir, "http://localhost:3000");
      const [a, b, c] = ["a", "b", "c"].map((x) => pack(x));
      for (const z of [a, b, c]) await st.put(sha1(z), z);
      const old = new Date("2026-01-01T00:00:00Z");
      utimesSync(st.pathFor(sha1(a)), old, old);
      utimesSync(st.pathFor(sha1(b)), old, old);
      const referenced = new Set([sha1(b)]);
      const now = new Date("2026-10-10T00:00:00Z");
      const dry = await runPackGc(st, referenced, { now, olderThanDays: 30 });
      assert.equal(dry.dryRun, true);
      assert.deepEqual(dry.delete.map((o) => o.sha1), [sha1(a)]);
      assert.equal(await st.exists(sha1(a)), true);
      const real = await runPackGc(st, referenced, { now, olderThanDays: 30, dryRun: false });
      assert.deepEqual(real.deleted, [sha1(a)]);
      assert.equal(real.keptReferenced, 1);
      assert.equal(real.keptYoung, 1);
      assert.deepEqual((await st.list()).map((o) => o.sha1).sort(), [sha1(b), sha1(c)].sort());
      assert.throws(() => planPackGc([], new Set(), { now, olderThanDays: 0 }));
    } finally { rmSync(dir, { recursive: true, force: true }); }
  });
});

describe("S3Store (fake fetch, no network)", () => {
  type Call = { method: string; url: string; headers: Record<string, string>; body: Buffer | null };
  function fakeS3() {
    const objects = new Map<string, { body: Buffer; headers: Record<string, string>; at: string }>();
    const calls: Call[] = [];
    const f = (async (input: string | URL | Request, init?: RequestInit) => {
      const url = String(input);
      const headers = init?.headers as Record<string, string>;
      const body = init?.body ? Buffer.from(init.body as Uint8Array) : null;
      calls.push({ method: String(init?.method), url, headers, body });
      if (!/^AWS4-HMAC-SHA256 Credential=AK\/\d{8}\/auto\/s3\/aws4_request, SignedHeaders=[a-z0-9;-]+, Signature=[0-9a-f]{64}$/.test(headers.authorization)) return new Response("denied", { status: 403 });
      const u = new URL(url);
      const key = decodeURIComponent(u.pathname.replace(/^\/bucket-1\//, ""));
      if (init?.method === "GET" && u.searchParams.get("list-type") === "2") {
        const items = [...objects.entries()].filter(([k]) => k.startsWith(u.searchParams.get("prefix") ?? "")).map(([k, v]) => `<Contents><Key>${k}</Key><LastModified>${v.at}</LastModified><Size>${v.body.length}</Size></Contents>`);
        return new Response(`<?xml version="1.0"?><ListBucketResult><IsTruncated>false</IsTruncated>${items.join("")}<Contents><Key>packs/other.txt</Key><LastModified>${new Date().toISOString()}</LastModified><Size>1</Size></Contents></ListBucketResult>`, { status: 200 });
      }
      if (init?.method === "HEAD") return new Response(null, { status: objects.has(key) ? 200 : 404 });
      if (init?.method === "PUT") { objects.set(key, { body: body!, headers, at: "2026-01-01T00:00:00.000Z" }); return new Response("", { status: 200 }); }
      if (init?.method === "DELETE") { const had = objects.delete(key); return new Response(null, { status: had ? 204 : 404 }); }
      return new Response("?", { status: 400 });
    }) as typeof fetch;
    return { f, objects, calls };
  }
  const mk = (f: typeof fetch) => new S3Store({ endpoint: "https://acct.storage.example", bucket: "bucket-1", region: "auto", credentials: { accessKeyId: "AK", secretAccessKey: "SK" }, publicBase: "https://packs.example.com", prefix: "packs", fetch: f, now: () => new Date("2026-10-10T00:00:00Z") });
  it("puts with immutable cache headers and a signed body hash, skips existing objects, lists and deletes", async () => {
    const s3 = fakeS3();
    const st = mk(s3.f);
    const z = pack("s3");
    const h = sha1(z);
    const r = await st.put(h, z);
    assert.equal(r.created, true);
    const put = s3.calls.find((c) => c.method === "PUT")!;
    assert.equal(put.url, `https://acct.storage.example/bucket-1/packs/p/${h}.zip`);
    assert.equal(put.headers["cache-control"], IMMUTABLE_CACHE_CONTROL);
    assert.equal(put.headers["content-type"], "application/zip");
    assert.equal(put.headers["x-amz-content-sha256"], sha256Hex(z));
    assert.equal(put.headers.host, undefined, "fetch sets Host itself");
    assert.equal((await st.put(h, z)).created, false);
    assert.equal(s3.calls.filter((c) => c.method === "PUT").length, 1);
    assert.equal(await st.exists(h), true);
    assert.equal(st.urlFor(h), `https://packs.example.com/p/${h}.zip`);
    const listed = await st.list();
    assert.deepEqual(listed.map((o) => [o.sha1, o.size]), [[h, z.length]]);
    assert.equal(await st.delete(h), true);
    assert.equal(await st.exists(h), false);
    await assert.rejects(st.put(h, pack("other")), /does not match/);
  });
  it("refuses insecure endpoints, bad buckets and missing credentials", () => {
    const f = fakeS3().f;
    assert.throws(() => new S3Store({ endpoint: "http://acct.storage.example", bucket: "b-1x", region: "auto", credentials: { accessKeyId: "a", secretAccessKey: "b" }, publicBase: "https://p.example", fetch: f }));
    assert.throws(() => new S3Store({ endpoint: "https://acct.storage.example", bucket: "B_bad", region: "auto", credentials: { accessKeyId: "a", secretAccessKey: "b" }, publicBase: "https://p.example", fetch: f }));
    assert.throws(() => new S3Store({ endpoint: "https://acct.storage.example", bucket: "bucket", region: "auto", credentials: { accessKeyId: "", secretAccessKey: "" }, publicBase: "https://p.example", fetch: f }));
  });
  it("parseListObjects ignores foreign keys", () => {
    const h = "1".repeat(40);
    const xml = `<Contents><Key>p/${h}.zip</Key><LastModified>2026-01-01T00:00:00Z</LastModified><Size>5</Size></Contents><Contents><Key>p/notapack.zip</Key><LastModified>2026-01-01T00:00:00Z</LastModified><Size>5</Size></Contents>`;
    assert.deepEqual(parseListObjects(xml, "p/").map((o) => o.sha1), [h]);
  });
});

