describe("pack loader config (pure install logic)", () => {
  const urlFor = (s: string) => publicPackUrl("https://packs.example.com", s);
  const A = "a".repeat(40), B = "b".repeat(40), C = "c".repeat(40);
  it("uuidV5 matches the RFC 4122 DNS example and pack ids are stable per (namespace, role)", () => {
    assert.equal(uuidV5("6ba7b810-9dad-11d1-80b4-00c04fd430c8", "www.example.com"), "2ed6657d-e927-568b-95e1-2665a8aea6a2");
    assert.equal(packIdFor("nx_abcd1234", "main"), packIdFor("nx_abcd1234", "main"));
    assert.notEqual(packIdFor("nx_abcd1234", "main"), packIdFor("nx_abcd1234", "models"));
    assert.notEqual(packIdFor("nx_abcd1234", "main"), packIdFor("nx_abcd1235", "main"));
    assert.throws(() => packIdFor("Bad NS", "main"));
  });
  it("add -> update -> unchanged -> remove, keeping stacking order and immutable URLs", () => {
    const r1 = applyPackChange(null, { op: "upsert", namespace: "nx_aaaa1111", role: "main", sha1: A, required: true, prompt: "Coins" }, { urlFor });
    assert.ok(r1.ok && r1.action === "added" && r1.changed);
    const r2 = applyPackChange(r1.config, { op: "upsert", namespace: "nx_bbbb2222", role: "main", sha1: B }, { urlFor });
    assert.ok(r2.ok && r2.action === "added");
    assert.deepEqual(r2.config.packs.map((p) => p.sha1), [A, B]);
    assert.equal(r2.config.packs[1].required, false);
    const r3 = applyPackChange(r2.config, { op: "upsert", namespace: "nx_aaaa1111", role: "main", sha1: C, required: true, prompt: "Coins" }, { urlFor });
    assert.ok(r3.ok && r3.action === "updated");
    assert.deepEqual(r3.config.packs.map((p) => [p.sha1, p.url]), [[C, urlFor(C)], [B, urlFor(B)]], "position kept, URL follows the sha1");
    assert.equal(r3.config.packs[0].id, r1.config.packs[0].id, "same id across versions");
    const r4 = applyPackChange(r3.config, { op: "upsert", namespace: "nx_aaaa1111", role: "main", sha1: C, required: true, prompt: "Coins" }, { urlFor });
    assert.ok(r4.ok && r4.action === "unchanged" && !r4.changed);
    const r5 = applyPackChange(r4.config, { op: "remove", namespace: "nx_aaaa1111", role: "main" }, { urlFor });
    assert.ok(r5.ok && r5.action === "removed" && r5.config.packs.length === 1);
    const r6 = applyPackChange(r5.config, { op: "remove", namespace: "nx_aaaa1111", role: "main" }, { urlFor });
    assert.ok(r6.ok && r6.action === "absent" && !r6.changed);
    assert.deepEqual([...referencedSha1s([r3.config])].sort(), [B, C]);
    assert.equal(r1.config.packs.length, 1, "inputs are never mutated");
  });
  it("serialization is deterministic and the plugin-side validation accepts exactly what Nxeon writes", () => {
    const r = applyPackChange(null, { op: "upsert", namespace: "nx_aaaa1111", role: "main", sha1: A, required: true }, { urlFor });
    assert.ok(r.ok);
    const text = serializeLoaderConfig(r.config);
    assert.equal(text, serializeLoaderConfig(JSON.parse(text)));
    assert.ok(text.endsWith("\n"));
    const v = validateLoaderConfig(JSON.parse(text), { requireHttps: true });
    assert.ok(v.ok);
  });
  it("validation rejects the whole config on any bad entry", () => {
    const id = packIdFor("nx_aaaa1111", "main");
    const bad = (packs: unknown[], schema = 1) => validateLoaderConfig({ schema, packs });
    const good = { id, url: urlFor(A), sha1: A, required: true };
    assert.equal(bad([good]).ok, true);
    assert.equal(bad([good], 2).ok, false);
    for (const p of [{ ...good, id: "nope" }, { ...good, sha1: "XYZ" }, { ...good, url: "ftp://x/y.zip" }, { ...good, required: "yes" }, { ...good, prompt: "x".repeat(301) }]) assert.equal(bad([p]).ok, false, JSON.stringify(p));
    const dup = bad([good, { ...good, sha1: B }]);
    assert.ok(!dup.ok && dup.errors.some((e) => e.code === "duplicate_id"));
    assert.equal(validateLoaderConfig({ schema: 1, packs: [{ ...good, url: "http://localhost:3000/p/x.zip" }] }, { requireHttps: true }).ok, false);
    assert.equal(validateLoaderConfig([]).ok, false);
  });
  it("caps the number of packs, refuses a broken current config and bad input", () => {
    let c: LoaderConfig | null = null;
    for (let i = 0; i < MAX_PACKS; i++) {
      const r = applyPackChange(c, { op: "upsert", namespace: `nx_p${String(i).padStart(7, "0")}`, role: "main", sha1: A }, { urlFor });
      assert.ok(r.ok); c = r.config;
    }
    const over = applyPackChange(c, { op: "upsert", namespace: "nx_overflow", role: "main", sha1: A }, { urlFor });
    assert.ok(!over.ok && over.code === "too_many");
    const broken = applyPackChange({ schema: 1, packs: [{ id: "x", url: "y", sha1: "z", required: true }] }, { op: "upsert", namespace: "nx_aaaa1111", role: "main", sha1: A }, { urlFor });
    assert.ok(!broken.ok && broken.code === "current_invalid");
    const badSha = applyPackChange(null, { op: "upsert", namespace: "nx_aaaa1111", role: "main", sha1: "nope" }, { urlFor });
    assert.ok(!badSha.ok && badSha.code === "bad_sha1");
  });
  it("warns about an existing pack owner or a server.properties pack (data from the server inventory)", () => {
    const r = applyPackChange(null, { op: "upsert", namespace: "nx_aaaa1111", role: "main", sha1: A }, { urlFor }, { plugins: ["LuckPerms", "Oraxen"], serverProperties: { "resource-pack": "https://elsewhere/x.zip" } });
    assert.ok(r.ok);
    assert.deepEqual(r.warnings.map((w) => w.code), ["pack_owner_present", "server_properties_pack"]);
    assert.match(r.warnings[0].message, /Oraxen/);
    const clean = applyPackChange(null, { op: "upsert", namespace: "nx_aaaa1111", role: "main", sha1: A }, { urlFor }, { plugins: ["LuckPerms"], serverProperties: { "resource-pack": "" } });
    assert.ok(clean.ok && clean.warnings.length === 0);
  });
  it("server.properties fallback holds exactly one pack", () => {
    const one = applyPackChange(null, { op: "upsert", namespace: "nx_aaaa1111", role: "main", sha1: A, required: true, prompt: "Coins" }, { urlFor });
    assert.ok(one.ok);
    const f = serverPropertiesFallback(one.config);
    assert.ok(f.ok);
    assert.deepEqual(f.keys, { "resource-pack": urlFor(A), "resource-pack-id": one.config.packs[0].id, "resource-pack-sha1": A, "resource-pack-prompt": '{"text":"Coins"}', "require-resource-pack": "true" });
    const none = serverPropertiesFallback({ schema: 1, packs: [] });
    assert.ok(none.ok && none.keys["resource-pack"] === "" && none.keys["require-resource-pack"] === "false");
    const two = applyPackChange(one.config, { op: "upsert", namespace: "nx_bbbb2222", role: "main", sha1: B }, { urlFor });
    assert.ok(two.ok);
    assert.equal(serverPropertiesFallback(two.config).ok, false);
  });
});
