cat > test/cyrus-managed.test.ts <<'EOF'
// Cyrus managed plugins (R0): catalog data, family pins, ref-count rules, the in-memory installer, the real
// engine installer against a LOCAL fake guest (real lib/mods/engine.ts placement, backup, state file; no SSH),
// and Pack Loader config delivery onto that fake guest. No DB, no network.
//   tsx --test test/cyrus-managed.test.ts
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import { mkdtempSync, rmSync, writeFileSync, mkdirSync } from "node:fs";
import { tmpdir } from "node:os";
import path from "node:path";
import { loadCatalog, pinFor, validateCatalog, seedCatalog, type CatalogEntry } from "../lib/cyrus/managed/catalog";
import { planEnsure, planRelease, userRemovable, type ManagedRow } from "../lib/cyrus/managed/refs";
import { engineManagedInstaller, memoryInstaller, managedResolution, readManagedArtifact, MANAGED_REAL_FLAG } from "../lib/cyrus/managed/installer";
import { LocalGuestFs, seedSandboxGuest } from "../lib/mods/guest-fs";
import { loadState } from "../lib/mods/engine";
import { zip } from "../lib/cyrus/textures/zip";
import { readLoaderConfig, writeLoaderConfig } from "../lib/cyrus/packhost/deliver";
import { applyPackChange } from "../lib/cyrus/packhost/loader-config";
import { publicPackUrl } from "../lib/cyrus/packhost/types";

const sha256 = (b: Buffer) => createHash("sha256").update(b).digest("hex");
const jar = (v: string) => zip([{ path: "plugin.yml", data: Buffer.from(`name: NxeonPackLoader\nversion: ${v}\nmain: x.Y\napi-version: '1.21'\n`) }, { path: "x/Y.class", data: Buffer.from(v) }]);
const entry = (over: Partial<CatalogEntry> = {}): CatalogEntry => ({
  key: "nxeon-pack-loader", displayName: "Nxeon Pack Loader", family: "1.21", version: "0.1.0", pluginName: "NxeonPackLoader", source: "nxeon-built",
  sourceRef: "build.sh", sha256: "0".repeat(64), artifact: "nxeon-pack-loader/NxeonPackLoader-0.1.0.jar", javaRelease: 21, ...over,
});

describe("managed plugin catalog (data)", () => {
  it("the shipped catalog is valid: nxeon-pack-loader pinned for both families, no BetterModel yet", () => {
    const c = loadCatalog();
    assert.deepEqual(c.map((e) => `${e.key}@${e.family}`).sort(), ["nxeon-pack-loader@1.21", "nxeon-pack-loader@26"]);
    assert.ok(c.every((e) => /^[0-9a-f]{64}$/.test(e.sha256) && e.javaRelease === 21 && e.pluginName === "NxeonPackLoader"));
    assert.ok(!c.some((e) => /bet+e?r?model/i.test(e.key)));
  });
  it("validation catches bad and duplicate entries", () => {
    assert.equal(validateCatalog({ schema: 2, entries: [] }).ok, false);
    const bad = validateCatalog({ schema: 1, entries: [{ ...entry(), key: "Bad Key", sha256: "x", artifact: "../x", family: "1.20" }, entry(), entry()] });
    assert.ok(!bad.ok);
    const e = bad.errors.join("\n");
    for (const s of ["key", "sha256", "artifact", "family", "duplicate"]) assert.match(e, new RegExp(s));
  });
  it("pins per family from the version registry and fails closed", () => {
    const cat = [entry(), entry({ family: "26", version: "0.2.0", javaRelease: 25 })];
    const a = pinFor(cat, "nxeon-pack-loader", "1.21.11");
    assert.ok(a.ok && a.entry.version === "0.1.0" && a.family === "1.21");
    const b = pinFor(cat, "nxeon-pack-loader", "26.2");
    assert.ok(b.ok && b.entry.version === "0.2.0" && b.family === "26");
    assert.equal((pinFor(cat, "nxeon-pack-loader", "1.20.4") as { code: string }).code, "unknown_version");
    assert.equal((pinFor(cat, "betteemodel", "26.2") as { code: string }).code, "unknown_plugin");
    assert.equal((pinFor([entry()], "nxeon-pack-loader", "26.2") as { code: string }).code, "no_pin");
    assert.equal((pinFor([entry({ javaRelease: 25 })], "nxeon-pack-loader", "1.21.11") as { code: string }).code, "java_too_old");
  });
  it("seedCatalog upserts one row per (key, family)", async () => {
    const calls: { where: unknown }[] = [];
    const n = await seedCatalog({ cyrusManagedPlugin: { upsert: async (a: { where: unknown }) => { calls.push(a); return null; } } });
    assert.equal(n, 2);
    assert.deepEqual(calls.map((c) => c.where), [{ key_family: { key: "nxeon-pack-loader", family: "1.21" } }, { key_family: { key: "nxeon-pack-loader", family: "26" } }]);
  });
});

describe("ref-count rules (pure)", () => {
  const pin = entry({ sha256: "1".repeat(64) });
  const row = (over: Partial<ManagedRow> = {}): ManagedRow => ({ status: "installed", version: "0.1.0", sha256: pin.sha256, family: "1.21", dependents: ["mod:a"], ...over });
  it("ensure: install first, add refs, upgrade on a new pin, busy while changing, retry after failure", () => {
    assert.deepEqual(planEnsure(null, "mod:a", pin), { kind: "install", dependents: ["mod:a"] });
    assert.deepEqual(planEnsure(row(), "mod:a", pin), { kind: "noop", dependents: ["mod:a"] });
    assert.deepEqual(planEnsure(row(), "project:p1", pin), { kind: "addRef", dependents: ["mod:a", "project:p1"] });
    assert.equal(planEnsure(row({ version: "0.0.9" }), "mod:a", pin).kind, "upgrade");
    assert.equal(planEnsure(row({ family: "26" }), "mod:a", pin).kind, "upgrade");
    assert.equal(planEnsure(row({ status: "installing" }), "mod:b", pin).kind, "busy");
    assert.equal(planEnsure(row({ status: "removing" }), "mod:b", pin).kind, "busy");
    assert.deepEqual(planEnsure(row({ status: "failed" }), "mod:b", pin), { kind: "install", dependents: ["mod:a", "mod:b"] });
    assert.deepEqual(planEnsure(row({ status: "removed", dependents: [] }), "mod:b", pin), { kind: "install", dependents: ["mod:b"] });
    assert.throws(() => planEnsure(null, "user:x", pin));
  });
  it("release: drop a ref, remove with the last one, never while busy; customer removal only with no dependents", () => {
    const two = row({ dependents: ["mod:a", "mod:b"] });
    assert.deepEqual(planRelease(two, "mod:a"), { kind: "decRef", dependents: ["mod:b"] });
    assert.deepEqual(planRelease(row(), "mod:a"), { kind: "remove", dependents: [] });
    assert.equal(planRelease(row(), "mod:zzz").kind, "noop");
    assert.equal(planRelease(null, "mod:a").kind, "noop");
    assert.equal(planRelease(row({ status: "installing" }), "mod:a").kind, "busy");
    assert.equal(planRelease(row({ status: "failed", dependents: [] }), "mod:a").kind, "remove");
    assert.deepEqual(userRemovable(two), { ok: false, dependents: ["mod:a", "mod:b"] });
    assert.deepEqual(userRemovable(row({ dependents: [] })), { ok: true });
  });
});

describe("installers", () => {
  it("memoryInstaller records what would be on each server", async () => {
    const m = memoryInstaller({ fail: (op, r) => (op === "install" && r.serverId === "bad" ? "boom" : null) });
    assert.deepEqual(await m.install({ serverId: "s1", entry: entry(), previousVersion: null }), { ok: true, version: "0.1.0", sha256: "0".repeat(64) });
    assert.deepEqual(await m.install({ serverId: "bad", entry: entry(), previousVersion: null }), { ok: false, error: "boom" });
    assert.equal(m.servers.get("s1")!.get("nxeon-pack-loader")!.version, "0.1.0");
    await m.remove({ serverId: "s1", key: "nxeon-pack-loader", pluginName: "NxeonPackLoader", version: "0.1.0" });
    assert.equal(m.servers.get("s1")!.size, 0);
  });
  it("the real engine installer is OFF unless the flag is 1 (and then touches nothing when off)", async () => {
    let opened = 0;
    const inst = engineManagedInstaller({ open: async () => { opened++; throw new Error("must not open"); }, env: {} });
    const r = await inst.install({ serverId: "s1", entry: entry(), previousVersion: null });
    assert.ok(!r.ok && r.error.includes(MANAGED_REAL_FLAG));
    assert.equal((await inst.remove({ serverId: "s1", key: "k", pluginName: null, version: null })).ok, false);
    assert.equal(opened, 0);
  });
  it("readManagedArtifact verifies the pinned sha256 and stays inside the managed dir", async () => {
    const dir = mkdtempSync(path.join(tmpdir(), "cyrus-managed-art-"));
    try {
      const b = jar("0.1.0");
      mkdirSync(path.join(dir, "nxeon-pack-loader"));
      writeFileSync(path.join(dir, "nxeon-pack-loader/NxeonPackLoader-0.1.0.jar"), b);
      assert.deepEqual(await readManagedArtifact(entry({ sha256: sha256(b) }), dir), b);
      await assert.rejects(readManagedArtifact(entry(), dir), /does not match the pin/);
      await assert.rejects(readManagedArtifact(entry({ sha256: sha256(b) }), "relative"), /absolute/);
    } finally { rmSync(dir, { recursive: true, force: true }); }
  });
  it("with the flag on, places / upgrades / removes the jar through the real Mods engine on a local fake guest", async () => {
    const root = mkdtempSync(path.join(tmpdir(), "cyrus-managed-guest-"));
    try {
      const fs = new LocalGuestFs(root);
      await seedSandboxGuest(fs, "minecraft", "paper");
      const server = { id: "srv-1", family: "minecraft", variant: "paper", pinnedVersion: "1.21.11", config: null };
      const jars: Record<string, Buffer> = { "0.1.0": jar("0.1.0"), "0.2.0": jar("0.2.0") };
      const inst = engineManagedInstaller({ open: async () => ({ fs, server }), readArtifact: async (e) => jars[e.version], env: { [MANAGED_REAL_FLAG]: "1" } });
      const v1 = entry({ sha256: sha256(jars["0.1.0"]) });
      const r1 = await inst.install({ serverId: "srv-1", entry: v1, previousVersion: null });
      assert.ok(r1.ok, JSON.stringify(r1));
      assert.deepEqual(await fs.readFile("/opt/mc/plugins/NxeonPackLoader.jar"), jars["0.1.0"]);
      let st = await loadState(fs, "minecraft");
      assert.equal(st.packages["nxeon-managed:nxeon-pack-loader"].version, "0.1.0");
      assert.equal(st.roots["managed:nxeon-pack-loader"].key, "nxeon-managed:nxeon-pack-loader");
      const v2 = entry({ version: "0.2.0", sha256: sha256(jars["0.2.0"]) });
      const r2 = await inst.install({ serverId: "srv-1", entry: v2, previousVersion: "0.1.0" });
      assert.ok(r2.ok, JSON.stringify(r2));
      assert.deepEqual(await fs.readFile("/opt/mc/plugins/NxeonPackLoader.jar"), jars["0.2.0"]);
      st = await loadState(fs, "minecraft");
      assert.equal(st.packages["nxeon-managed:nxeon-pack-loader"].version, "0.2.0");
      const r3 = await inst.remove({ serverId: "srv-1", key: "nxeon-pack-loader", pluginName: "NxeonPackLoader", version: "0.2.0" });
      assert.ok(r3.ok, JSON.stringify(r3));
      assert.equal(await fs.stat("/opt/mc/plugins/NxeonPackLoader.jar"), null);
      st = await loadState(fs, "minecraft");
      assert.equal(st.packages["nxeon-managed:nxeon-pack-loader"], undefined);
    } finally { rmSync(root, { recursive: true, force: true }); }
  });
  it("managedResolution is a single prefetched plugin jar (no download)", () => {
    const b = jar("0.1.0");
    const r = managedResolution(entry({ sha256: sha256(b) }), b);
    assert.equal(r.packages.length, 1);
    assert.equal(r.packages[0].placement, "plugin-jar");
    assert.equal(r.packages[0].file.filename, "NxeonPackLoader.jar");
    assert.equal(r.packages[0].prefetched, b);
  });
});

describe("Pack Loader config delivery onto a (fake) guest", () => {
  it("writes atomically, is a no-op when unchanged, reads back, and refuses invalid configs", async () => {
    const root = mkdtempSync(path.join(tmpdir(), "cyrus-deliver-"));
    try {
      const fs = new LocalGuestFs(root);
      await seedSandboxGuest(fs, "minecraft", "paper");
      assert.deepEqual(await readLoaderConfig(fs), { ok: true, config: null });
      const r = applyPackChange(null, { op: "upsert", namespace: "nx_abcd1234", role: "main", sha1: "a".repeat(40), required: true }, { urlFor: (s) => publicPackUrl("https://packs.example.com", s) });
      assert.ok(r.ok);
      assert.equal(await writeLoaderConfig(fs, r.config), true);
      assert.equal(await writeLoaderConfig(fs, r.config), false);
      const back = await readLoaderConfig(fs);
      assert.ok(back.ok && back.config!.packs[0].id === r.config.packs[0].id);
      assert.equal(await fs.stat("/opt/mc/plugins/NxeonPackLoader/packs.json.nxeon-part"), null);
      await assert.rejects(writeLoaderConfig(fs, { schema: 1, packs: [{ ...r.config.packs[0], url: "http://insecure.example/p/x.zip" }] }), /invalid/);
      await fs.writeFile("/opt/mc/plugins/NxeonPackLoader/packs.json", Buffer.from("{nope"));
      assert.equal((await readLoaderConfig(fs)).ok, false);
    } finally { rmSync(root, { recursive: true, force: true }); }
  });
});
EOF
