    const r1 = await S.ensureManagedPlugin(deps, { serverId: s, key: KEY, mcVersion: "1.21.11", dependent: "mod:m1" });
    assert.deepEqual(r1, { ok: true, action: "installed", version: "0.1.0", refCount: 1 });
    const r2 = await S.ensureManagedPlugin(deps, { serverId: s, key: KEY, mcVersion: "1.21.11", dependent: "project:p1" });
    assert.deepEqual(r2, { ok: true, action: "ref_added", version: "0.1.0", refCount: 2 });
    const r3 = await S.ensureManagedPlugin(deps, { serverId: s, key: KEY, mcVersion: "1.21.11", dependent: "mod:m1" });
    assert.equal(r3.ok && r3.action, "already");
    assert.equal(inst.calls.filter((c) => c.op === "install").length, 1);
    const row = await db.cyrusServerManagedPlugin.findUnique({ where: { serverId_key: { serverId: s, key: KEY } } });
    assert.equal(row!.status, "installed");
    assert.deepEqual(row!.dependents, ["mod:m1", "project:p1"]);
    assert.equal(row!.family, "1.21");
    assert.ok(row!.installedAt);
    assert.deepEqual(await S.canUserRemove(db, s, KEY), { ok: false, dependents: ["mod:m1", "project:p1"] });

    assert.deepEqual(await S.releaseManagedPlugin(deps, { serverId: s, key: KEY, dependent: "mod:m1" }), { ok: true, action: "ref_dropped", refCount: 1 });
    assert.equal(inst.calls.filter((c) => c.op === "remove").length, 0, "still depended on: never removed");
    assert.deepEqual(await S.releaseManagedPlugin(deps, { serverId: s, key: KEY, dependent: "mod:nope" }), { ok: true, action: "not_held", refCount: 1 });
    assert.deepEqual(await S.releaseManagedPlugin(deps, { serverId: s, key: KEY, dependent: "project:p1" }), { ok: true, action: "removed", refCount: 0 });
    assert.equal(inst.servers.get(s)!.size, 0);
    const gone = await db.cyrusServerManagedPlugin.findUnique({ where: { serverId_key: { serverId: s, key: KEY } } });
    assert.equal(gone!.status, "removed");
    assert.equal(gone!.version, null);
    assert.deepEqual(await S.canUserRemove(db, s, KEY), { ok: true });
    // Re-ensure after removal installs again.
    const again = await S.ensureManagedPlugin(deps, { serverId: s, key: KEY, mcVersion: "1.21.11", dependent: "mod:m2" });
    assert.equal(again.ok && again.action, "installed");
  });

  it("follows the family pin: a server moving 1.21 -> 26 is upgraded; a bumped pin upgrades in place", async () => {
    const inst = I.memoryInstaller();
    const base = C.loadCatalog();
    const s = srv("b");
    const cat26 = base.map((e) => (e.family === "26" ? { ...e, version: "0.9.0", sha256: "9".repeat(64) } : e));
    const deps = { db, installer: inst, catalog: cat26 };
    assert.equal((await S.ensureManagedPlugin(deps, { serverId: s, key: KEY, mcVersion: "1.21.11", dependent: "mod:m1" })).ok, true);
    const up = await S.ensureManagedPlugin(deps, { serverId: s, key: KEY, mcVersion: "26.2", dependent: "mod:m1" });
    assert.deepEqual(up, { ok: true, action: "upgraded", version: "0.9.0", refCount: 1 });
    const row = await db.cyrusServerManagedPlugin.findUnique({ where: { serverId_key: { serverId: s, key: KEY } } });
    assert.equal(row!.family, "26");
    assert.equal(row!.sha256, "9".repeat(64));
    assert.equal(inst.calls.at(-1)!.version, "0.9.0");
    assert.equal((await S.ensureManagedPlugin(deps, { serverId: s, key: KEY, mcVersion: "1.20.4", dependent: "mod:m1" }) as { code: string }).code, "unknown_version");
    assert.equal((await S.ensureManagedPlugin(deps, { serverId: s, key: "betteemodel", mcVersion: "26.2", dependent: "mod:m1" }) as { code: string }).code, "unknown_plugin");
    assert.equal((await S.ensureManagedPlugin(deps, { serverId: s, key: KEY, mcVersion: "26.2", dependent: "nobody" }) as { code: string }).code, "bad_input");
  });

  it("a failed install keeps the dependent and the next ensure retries; a failed removal can be retried", async () => {
    let failInstall = true, failRemove = true;
    const inst = I.memoryInstaller({ fail: (op) => (op === "install" && failInstall ? "server offline" : op === "remove" && failRemove ? "ssh refused" : null) });
    const deps = { db, installer: inst, catalog: C.loadCatalog() };
    const s = srv("c");
    const f = await S.ensureManagedPlugin(deps, { serverId: s, key: KEY, mcVersion: "26.2", dependent: "mod:m1" });
    assert.deepEqual(f, { ok: false, code: "install_failed", error: "server offline" });
    let row = await db.cyrusServerManagedPlugin.findUnique({ where: { serverId_key: { serverId: s, key: KEY } } });
    assert.equal(row!.status, "failed");
    assert.deepEqual(row!.dependents, ["mod:m1"]);
    failInstall = false;
    const ok = await S.ensureManagedPlugin(deps, { serverId: s, key: KEY, mcVersion: "26.2", dependent: "mod:m1" });
    assert.equal(ok.ok && ok.action, "installed");
    const rf = await S.releaseManagedPlugin(deps, { serverId: s, key: KEY, dependent: "mod:m1" });
    assert.deepEqual(rf, { ok: false, code: "remove_failed", error: "ssh refused" });
    row = await db.cyrusServerManagedPlugin.findUnique({ where: { serverId_key: { serverId: s, key: KEY } } });
    assert.equal(row!.status, "failed");
    assert.equal(row!.refCount, 0);
    failRemove = false;
    assert.deepEqual(await S.releaseManagedPlugin(deps, { serverId: s, key: KEY, dependent: "mod:m1" }), { ok: true, action: "removed", refCount: 0 });
  });

  it("concurrent ensures on one server: exactly one install runs, the rest get busy or a ref", async () => {
    let release!: () => void;
    const gate = new Promise<void>((r) => (release = r));
    const mem = I.memoryInstaller();
    const slow = { install: async (r: Parameters<typeof mem.install>[0]) => { await gate; return mem.install(r); }, remove: mem.remove };
    const deps = { db, installer: slow, catalog: C.loadCatalog() };
    const s = srv("d");
    const first = S.ensureManagedPlugin(deps, { serverId: s, key: KEY, mcVersion: "1.21.11", dependent: "mod:m1" });
    await new Promise((r) => setTimeout(r, 300));
    const others = await Promise.all(["mod:m2", "mod:m3"].map((d) => S.ensureManagedPlugin(deps, { serverId: s, key: KEY, mcVersion: "1.21.11", dependent: d })));
    assert.ok(others.every((o) => !o.ok && o.code === "busy"), JSON.stringify(others));
    release();
    assert.equal((await first).ok, true);
    assert.equal(mem.calls.filter((c) => c.op === "install").length, 1);
    // Racing creates of a brand-new row do not error.
    const s2 = srv("e");
    const race = await Promise.all(["mod:a", "mod:b", "mod:c"].map((d) => S.ensureManagedPlugin({ db, installer: I.memoryInstaller(), catalog: C.loadCatalog() }, { serverId: s2, key: KEY, mcVersion: "26.2", dependent: d })));
    assert.ok(race.every((r) => r.ok || r.code === "busy"), JSON.stringify(race));
    assert.ok(race.some((r) => r.ok && r.action === "installed"));
  });

  it("the catalog seeds into CyrusManagedPlugin idempotently", async () => {
    assert.equal(await C.seedCatalog(db), 2);
    assert.equal(await C.seedCatalog(db), 2);
    const rows = await db.cyrusManagedPlugin.findMany({ where: { key: KEY }, orderBy: { family: "asc" } });
    assert.deepEqual(rows.map((r) => [r.family, r.version, r.pluginName]), [["1.21", "0.1.0", "NxeonPackLoader"], ["26", "0.1.0", "NxeonPackLoader"]]);
  });
});
