export async function ensureManagedPlugin(deps: ManagedDeps, args: { serverId: string; key: string; mcVersion: string; dependent: string }): Promise<EnsureResult> {
  if (!args.serverId || !DEPENDENT_RE.test(args.dependent)) return { ok: false, code: "bad_input", error: "serverId and a dependent id (project:<id> or mod:<id>) are required" };
  const pin = pinFor(deps.catalog, args.key, args.mcVersion);
  if (!pin.ok) return { ok: false, code: pin.code, error: pin.error };
